require_once __DIR__.'/../includes/auth_check.php';require_once __DIR__.'/../config/database.php';$s=$pdo->prepare("SELECT p.*,c.nama_kategori FROM products p LEFT JOIN categories c ON c.id=p.category_id AND c.user_id=p.user_id WHERE p.user_id=? AND (p.stok=0 OR p.stok<=p.stok_minimum) ORDER BY p.stok ASC,p.nama_barang");$s->execute([current_user_id()]);$rows=$s->fetchAll();$pageTitle='Peringatan Stok';$active='alerts';require __DIR__.'/../includes/header.php';
?>
<div class="page-actions"><div><span class="eyebrow">PUSAT PERHATIAN</span><h1>Peringatan & restock</h1><p>Daftar barang yang perlu diperiksa atau dipertimbangkan untuk dibeli kembali.</p></div></div>
