<section class="panel"><div class="panel-heading"><div><h3>Barang membutuhkan perhatian</h3><p><?= count($rows) ?> barang perlu diperiksa</p></div></div><div class="table-wrap"><table><thead><tr><th>Nama barang</th><th>Kategori</th><th>Stok sekarang</th><th>Batas minimum</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $r):$empty=(int)$r['stok']===0; ?><tr><td><b><?= e($r['nama_barang']) ?></b><small class="sub-cell"><?= e($r['kode_barang']) ?></small></td><td><?= e($r['nama_kategori']??'-') ?></td><td><b><?= (int)$r['stok'].' '.e($r['satuan']) ?></b></td><td><?= (int)$r['stok_minimum'].' '.e($r['satuan']) ?></td><td><span class="badge <?= $empty?'badge-red':'badge-amber' ?>"><?= $empty?'Stok habis':'Stok menipis' ?></span></td><td><a class="text-link" href="../transactions/create.php?type=in">Catat barang masuk →</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state compact"><i data-lucide="check-circle-2"></i><b>Semua stok dalam kondisi aman</b><span>Belum ada barang yang berada di bawah batas minimum.</span></div></td></tr><?php endif; ?></tbody></table></div></section>
